record.field:
answer = payload or {}
result = answer.get('result') or {}
companies = env['res.company'].sudo().search([])
if 'balance' in answer:
    companies.write({'x_tb_online_balance': answer.get('balance') or 0})
if answer.get('state') != 'done':
    record.write({'x_state': 'error', 'x_error': answer.get('error') or 'error', 'x_result': str(answer)})
elif answer.get('service') == 'register':
    send = env.ref('l10n_ro_anaf_partner_online.action_tb_send').sudo()
    server = send.webhook_url.split('/iap_online/')[0]
    token = result.get('account_token') or ''
    send.write({'webhook_url': server + '/iap_online/anaf_partner_online?token=' + token})
    companies.write({'x_tb_online_token': token, 'x_tb_online_server': server})
    record.write({'x_state': 'done', 'x_error': False, 'x_result': 'Service activated'})
else:
    status = result.get('state')
    partner = record.x_partner_id
    if status == 'found' and partner:
        data = result.get('partner') or {}
        vals = {key: data[key] for key in ('name', 'vat', 'street', 'street2', 'city', 'zip', 'phone') if data.get(key)}
        country = env['res.country'].search([('code', '=', data.get('country_code') or 'RO')], limit=1)
        region = env['res.country.state'].search([('country_id', '=', country.id), ('code', '=', data.get('state_code') or '-')], limit=1)
        vals.update({
            'is_company': True,
            'country_id': country.id,
            'state_id': region.id or False,
            'x_anaf_vat_payer': bool(result.get('vat_payer')),
            'x_anaf_inactive': bool(result.get('inactive')),
            'x_anaf_struck_off': bool(result.get('struck_off')),
            'x_anaf_trade_register': result.get('trade_register') or False,
            'x_anaf_last_check': datetime.datetime.now(),
        })
        partner.write(vals)
        partner.message_post(body='Partner data updated from ANAF (Terrabit service).')
        record.write({'x_state': 'done', 'x_error': False, 'x_result': str(result)})
    else:
        messages = {
            'not_found': 'CUI not found at ANAF',
            'invalid': 'Invalid CUI',
            'unavailable': 'ANAF did not answer, please try again later',
        }
        record.write({'x_state': 'error', 'x_error': messages.get(status, status or 'error'), 'x_result': str(result)})
